                new \Phplrt\Parser\Grammar\Lexeme(self::T_OF, true),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_AS, true),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_SUPER, true),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_VIRTUAL_NAME, true),
                new \Phplrt\Parser\Grammar\Optional(33),
                new \Phplrt\Parser\Grammar\Concatenation([34, 35]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_DOUBLE_COLON, false),
                new \Phplrt\Parser\Grammar\Alternation([36, 37, 38]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_IDENTIFIER_MASK, true),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_WILDCARD, true),
                new \Phplrt\Parser\Grammar\Concatenation([24]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_THIS, true),
                new \Phplrt\Parser\Grammar\Alternation([36, 41]),
                new \Phplrt\Parser\Grammar\Concatenation([23, 42]),
                new \Phplrt\Parser\Grammar\Alternation([36, 37]),
                new \Phplrt\Parser\Grammar\Concatenation([44, 0, 45]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_PAREN_OPEN, false),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_PAREN_CLOSE, false),
                new \Phplrt\Parser\Grammar\Optional(47),
                new \Phplrt\Parser\Grammar\Repetition(48, 1, \INF),
                new \Phplrt\Parser\Grammar\Concatenation([49, 50, 51]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_BRACKET_OPEN, false),
                new \Phplrt\Parser\Grammar\Optional(0),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_BRACKET_CLOSE, true),
                new \Phplrt\Parser\Grammar\Optional(53),
                new \Phplrt\Parser\Grammar\Repetition(54, 1, \INF),
                new \Phplrt\Parser\Grammar\Concatenation([55, 3]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_AMPERSAND, false),
                new \Phplrt\Parser\Grammar\Optional(57),
                new \Phplrt\Parser\Grammar\Repetition(58, 1, \INF),
                new \Phplrt\Parser\Grammar\Concatenation([59, 2]),
                new \Phplrt\Parser\Grammar\Lexeme(self::T_UNION, false),
            ],
            initial: 0,
            reducers: [
                0 => self::reduceType(...),
                1 => $this->reduceUnionType(...),
                2 => $this->reduceIntersectionType(...),
                3 => $this->reduceNullableType(...),
                6 => $this->reduceListTypeOrOffsetAccess(...),
                8 => $this->reduceLiteral(...),
                20 => self::reduceNamedType(...),
                21 => self::reduceName(...),
                23 => self::reduceNamespace(...),
                36 => self::reduceIdentifierMask(...),
                37 => self::reduceWildcardMask(...),
                38 => self::reduceIdentifier(...),
                39 => self::reduceThisType(...),
                40 => self::reduceConstMaskType(...),
            ],
            expectations: self::PARSER_EXPECTATIONS,
            kept: self::PARSER_KEPT_TABLE,
            startPrediction: self::PARSER_START_PREDICTION_TABLE,
            choicePrediction: self::PARSER_CHOICE_PREDICTION_TABLE,
            sequencePrediction: self::PARSER_SEQUENCE_PREDICTION_TABLE,
        );
    }

    public function parse(\Phplrt\Contracts\Source\ReadableInterface $source): mixed
    {
        return $this->parser->parse($source);
    }

    private static function reduceType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        if (\is_array($children)) {
            return $children[0];
        }

        return $children;
    }

    private function reduceUnionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!isset($children[1])) {
            return $children[0];
        }

        // [type, type]
        if (!$this->features->unions) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('unions', $ctx);
        }

        return new Type\LogicalTypeNode\UnionTypeNode($children, $offset);
    }

    private function reduceIntersectionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!isset($children[1])) {
            return $children[0];
        }

        // [type, type, ...]
        if (!$this->features->intersections) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('intersections', $ctx);
        }

        return new Type\LogicalTypeNode\IntersectionTypeNode($children, $offset);
    }

    private function reduceNullableType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (\count($children) === 2) {
            if (!$this->features->nullables) {
                throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('nullables', $ctx);
            }

            return new Type\WrappingTypeNode\NullableTypeNode($children[1], $offset);
        }

        return $children[0];
    }

    private function reduceListTypeOrOffsetAccess(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;
        $length = $ctx->length;

        // No suffixes
        if (!\is_array($children)) {
            return $children;
        }

        // The children are the type and, for every suffix, the type inside of
        // the brackets (the key), if there is one, and the closing bracket
        $type = $children[0];

        for ($i = 1, $length = \count($children); $i < $length; ++$i) {
            // T[K], the closing bracket is behind the key
            if ($children[$i] instanceof Type\TypeNode) {
                if (!$this->features->offsets) {
                    throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('offsets', $ctx);
                }

                $type = new Type\WrappingTypeNode\TypeOffsetAccessTypeNode($type, $children[$i++], $offset);

                continue;
            }

            // T[]
            if (!$this->features->lists) {
                throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('lists', $ctx);
            }

            $type = new Type\WrappingTypeNode\TypesListTypeNode($type, $offset);
        }

        return $type;
    }

    private function reduceLiteral(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        /** @var \Phplrt\Contracts\Lexer\TokenInterface $children */
        if (!$this->features->literals) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('literals', $ctx);
        }

        return match ($children->id) {
            self::T_NULL => new Type\Literal\NullLiteralNode($children->value, $offset),
            self::T_TRUE => new Type\Literal\BoolLiteralNode(true, $children->value, $offset),
            self::T_FALSE => new Type\Literal\BoolLiteralNode(false, $children->value, $offset),
            self::T_FLOAT => $this->float->parse($children->value, $offset),
            self::T_INT_DEC => $this->decInt->parse($children->value, $offset),
            self::T_INT_HEX => $this->hexInt->parse($children->value, $offset),
            self::T_INT_BIN => $this->binInt->parse($children->value, $offset),
            self::T_INT_OCT => $this->octInt->parse($children->value, $offset),
            self::T_INT_OCT_LEGACY => $this->octLegacyInt->parse($children->value, $offset),
            self::T_SQ_STRING => $this->sqString->parse($children->value, $offset),
            default => $this->dqString->parse($children->value, $offset),
        };
    }

    private static function reduceNamedType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        $name = $children[0];
        $constant = $children[1] ?? null;

        // Foo, \Foo\Bar
        if ($constant === null) {
            return new Type\NamedTypeNode($name, null, null, $offset);
        }

        // Foo::BAR, a lone word is a constant
        if ($constant instanceof Type\Identifier) {
            return new Type\Constant\ClassConstTypeNode($name, $constant, $offset);
        }

        // Foo::BAR_*, anything else is a mask of constants
        return new Type\Constant\ClassConstMaskTypeNode($name, $constant, $offset);
    }

    private static function reduceName(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        // Some\Foo, \Foo
        if (\is_array($children)) {
            return new Type\Name($children[1]->value, $children[0], $offset);
        }

        // Foo, non-empty-string
        return new Type\Name($children->value, null, $offset);
    }

    private static function reduceNamespace(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        $kind = Type\NamespaceName\NamespaceKind::Qualified;

        if ($children->value[0] === Type\NamespaceName::DELIMITER) {
            $kind = Type\NamespaceName\NamespaceKind::FullyQualified;
        }

        return new Type\NamespaceName(\trim($children->value, Type\NamespaceName::DELIMITER), $kind, $offset);
    }

    private static function reduceIdentifierMask(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        $items = [];
        $position = $offset;

        foreach (\explode('*', $children->value) as $index => $word) {
            if ($index > 0) {
                $items[] = new Type\Constant\MaskNode\WildcardMaskNode($position++);
            }

            if ($word !== '') {
                $items[] = new Type\Identifier($word, $position);
                $position += \strlen($word);
            }
        }

        return new Type\Constant\MaskNode($items, $offset);
    }

    private static function reduceWildcardMask(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return new Type\Constant\MaskNode([new Type\Constant\MaskNode\WildcardMaskNode($offset)], $offset);
    }

    private static function reduceIdentifier(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return new Type\Identifier($children[0]->value, $offset);
    }

    private static function reduceThisType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return new Type\ThisTypeNode($offset);
    }

    private static function reduceConstMaskType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        // PHP_*
        if (!\is_array($children)) {
            return new Type\Constant\ConstMaskTypeNode($children, null, $offset);
        }

        // Foo\BAR_*, \*
        return new Type\Constant\ConstMaskTypeNode($children[1], $children[0], $offset);
    }
}
